package model; import java.io.Serializable; import java.time.LocalDateTime; public class Token implements Serializable { private static final long serialVersionUID=1L; private final int tokenId,serviceId; private final String studentId; private final boolean priority; private final LocalDateTime arrivalTime; private String status;
 public Token(int id,String sid,int service,boolean priority){tokenId=id;studentId=sid;serviceId=service;this.priority=priority;arrivalTime=LocalDateTime.now();status="Waiting";} public int getTokenId(){return tokenId;} public String getStudentId(){return studentId;} public int getServiceId(){return serviceId;} public boolean isPriority(){return priority;} public LocalDateTime getArrivalTime(){return arrivalTime;} public String getStatus(){return status;} public void setStatus(String s){status=s;} public void displayToken(){System.out.printf("%-8d %-12s %-9s %-12s %s%n",tokenId,studentId,priority?"Priority":"Normal",status,arrivalTime.toLocalTime().withNano(0));} }
